files = repo.list(".")
manifest = repo.read("Cargo.toml", missing_ok = True)
srcs = []
for d in ["src", "tests", "benches", "examples"]:
    try:
        srcs.append((d, repo.list(d)))
    except Exception:
        pass
return {"root": files, "manifest": manifest, "dirs": srcs}

